1	export type Item = {
2	  type: string;
3	  cursed?: boolean;
4	  enchantment?: number;
5	};
6	
7	export type Scenario = {
8	  customer: { yearsWithMHPCO: number };
9	  steps: { op: string; items: Item[] }[];
10	};
11	
12	export type ScenarioResult = {
13	  results: { premium: number }[];
14	};
15	
16	const BASE_PREMIUM_BY_ITEM_TYPE: Record<string, number> = {
17	  sword: 100,
18	  amulet: 60,
19	  staff: 80,
20	  potion: 40,
21	  rune: 25,
22	  moonstone: 25,
23	};
24	const FIRST_INSURANCE_SURCHARGE_PERCENT = 10;
25	const CURSE_SURCHARGE_PERCENT = 50;
26	const HIGH_ENCHANTMENT_THRESHOLD = 5;
27	const HIGH_ENCHANTMENT_SURCHARGE_PERCENT = 30;
28	const PROCESSING_FEE = 5;
29	
30	const percentOf = (amount: number, percent: number): number =>
31	  (amount * percent) / 100;
32	
33	const roundInMHPCOsFavour = (premium: number): number => Math.ceil(premium);
34	
35	const BLOCK_SIZE = 3;
36	const BLOCK_BASE_PREMIUM = 60;
37	
38	const countByType = (items: Item[]): Map<string, number> =>
39	  items.reduce(
40	    (counts, item) => counts.set(item.type, (counts.get(item.type) ?? 0) + 1),
41	    new Map<string, number>(),
42	  );
43	
44	const formsBuildingBlock = (count: number): boolean => count === BLOCK_SIZE;
45	
46	const basePremiumForAlikeItems = (type: string, count: number): number =>
47	  formsBuildingBlock(count)
48	    ? BLOCK_BASE_PREMIUM
49	    : count * BASE_PREMIUM_BY_ITEM_TYPE[type];
50	
51	const policyBasePremium = (items: Item[]): number =>
52	  [...countByType(items)]
53	    .map(([type, count]) => basePremiumForAlikeItems(type, count))
54	    .reduce((total, alikeItemsPremium) => total + alikeItemsPremium, 0);
55	
56	const itemBasePremium = (item: Item): number =>
57	  BASE_PREMIUM_BY_ITEM_TYPE[item.type];
58	
59	/**
60	 * Item-specific modifiers are percentages of the AFFECTED ITEM's own base
61	 * premium — unlike policy-wide modifiers, which apply to the policy base.
62	 */
63	const isHighlyEnchanted = (item: Item): boolean =>
64	  (item.enchantment ?? 0) >= HIGH_ENCHANTMENT_THRESHOLD;
65	
66	const surchargePercentFor = (item: Item): number =>
67	  (item.cursed ? CURSE_SURCHARGE_PERCENT : 0) +
68	  (isHighlyEnchanted(item) ? HIGH_ENCHANTMENT_SURCHARGE_PERCENT : 0);
69	
70	const itemSurcharges = (items: Item[]): number =>
71	  items.reduce(
72	    (total, item) =>
73	      total + percentOf(itemBasePremium(item), surchargePercentFor(item)),
74	    0,
75	  );
76	
77	const quotePremium = (items: Item[]): number => {
78	  const basePremium = policyBasePremium(items);
79	  return roundInMHPCOsFavour(
80	    basePremium +
81	      itemSurcharges(items) +
82	      percentOf(basePremium, FIRST_INSURANCE_SURCHARGE_PERCENT) +
83	      PROCESSING_FEE,
84	  );
85	};
86	
87	export const runScenario = (scenario: Scenario): ScenarioResult => ({
88	  results: scenario.steps.map((step) => ({
89	    premium: quotePremium(step.items),
90	  })),
91	});
